#include "experience.hpp"
#include "profiles.hpp"
#include "game_sessions.hpp"
#include <algorithm>
#include <sstream>
#include <stdexcept>
namespace hr {
bool section_matches(const std::string& label,const std::string& query){std::istringstream input(lower(query.substr(0,256)));auto haystack=lower(label);std::string term;while(input>>term)if(haystack.find(term)==std::string::npos)return false;return true;}
std::string game_center_report(const Store& store,const std::string& game){if(game.empty())return "YOUR GAME SESSION\n\nAdd a game in Games, then choose it here. Your profile, launch, HUD, replay, timeline and measured results are brought together on this page.\nProfiles stay opt-in; no settings are changed by opening this center.";auto profile=game_profile(store,game);std::ostringstream out;out<<"GAME SESSION / "<<utf8(std::filesystem::path(wide(game)).stem().wstring())<<"\n\n"<<profile_review(profile)<<"\n\nPER-FRAME BENCHMARKS\n";auto rows=store.of("benchmark");unsigned count=0;for(auto it=rows.rbegin();it!=rows.rend()&&count<5;++it)if(it->size()>=10&&lower((*it)[2])==lower(game)){++count;out<<(*it)[1]<<" / "<<(*it)[4]<<"\nAverage "<<(*it)[6]<<" FPS / 1% low "<<(*it)[7]<<" FPS / P95 "<<(*it)[8]<<" ms / spikes "<<(*it)[9]<<"\n";}if(!count)out<<"No per-frame capture for this game yet. Record with PresentMon in Game library, or import CSV in Benchmarks; sampled HUD FPS does not supply 1% lows or frame times.\n";out<<"\n"<<session_history(true,game,3);return out.str();}
namespace {std::string readable_change(const std::string& value,const std::string& kind){try{if(kind=="regvalue"&&value.rfind("4:",0)==0&&value.size()==10){auto bytes=unhex(value.substr(2));if(bytes.size()==4){DWORD number=0;memcpy(&number,bytes.data(),4);return std::to_string(number)+" (DWORD; stored "+value+")";}}if(kind=="service"&&value.size()>=3){auto n=std::stoul(value);return std::string(n==2?"Automatic":n==3?"Manual":n==4?"Disabled":"Service type "+std::to_string(n))+" (stored "+value+")";}if(kind=="mouse"){auto end=value.find(',');if(end!=std::string::npos)return "Pointer speed "+value.substr(0,end)+" / 20; Windows thresholds/acceleration "+value.substr(end+1);}}catch(const std::exception&){}return value;}}
std::string change_explanation(const Row& row){if(row.size()!=6||row[0]!="journal")throw std::runtime_error("Invalid recovery entry");std::ostringstream out;out<<"CHANGE / "<<row[1]<<"\nTarget: "<<row[2]<<(row[5].empty()?"":" / "+row[5])<<"\n\nOriginal state: "<<readable_change(row[3],row[1])<<"\nApplied state: "<<readable_change(row[4],row[1])<<"\n\n";auto kind=row[1],target=lower(row[2]+" "+row[5]);if(kind=="power")out<<"Purpose: a selected power profile changes Windows power behavior. Battery draw, fan noise and temperatures may increase. Takes effect immediately; no reboot normally needed.\n";else if(kind=="mouse")out<<"Purpose: change Windows pointer speed/acceleration. Raw-input games can use their own sensitivity. Takes effect immediately.\n";else if(kind=="service")out<<"Purpose: change service startup behavior. This does not stop an already running service. The effect may wait until the next start or reboot.\n";else if(kind=="regvalue"||kind=="registry"){out<<"Purpose: a reviewed Windows preference or policy. Current effective behavior can depend on Windows policy and hardware.\n";if(target.find("graphicsdrivers")!=std::string::npos||target.find("deviceguard")!=std::string::npos||target.find("dwm")!=std::string::npos)out<<"Restart/sign-out may be required. Review the originating System tool for hardware and security trade-offs.\n";else out<<"Restart requirement: consult the originating action; a registry write alone does not prove the effective feature changed.\n";}else out<<"Purpose and restart timing depend on the original action. The activity log retains its action details. No performance benefit is inferred from this backup.\n";out<<"\nRestore checks live state and refuses external changes or newer edits to the same setting. The original backup is retained on a conflict. Review the exact original/applied values above before restoring.\n";return out.str();}
DesktopScene portable_scene(DesktopScene scene){scene.display.clear();scene.video.clear();scene.wallpaper=false;scene.wall_mode=1;scene.pins.clear();scene.hidden_apps.clear();scene.notes="Your desktop. Your rules.";scene.location.clear();scene.latitude=scene.longitude=0;scene.widgets&=~32u;if(scene.board&&!scene.widgets)scene.board=false;validate_desktop_scene(scene);return scene;}
std::string shared_scene_file(const DesktopScene& scene){return encode({{"headroom-shared-scene","1",encode_desktop_scene(portable_scene(scene))}});}
DesktopScene read_shared_scene(const std::string& text){if(text.size()>65536)throw std::runtime_error("Shared scene exceeds 64 KiB");auto rows=decode(text);if(rows.size()!=1||rows[0].size()!=3||rows[0][0]!="headroom-shared-scene"||rows[0][1]!="1")throw std::runtime_error("Unknown shared scene format");auto scene=decode_desktop_scene(rows[0][2]);if(encode_desktop_scene(scene)!=encode_desktop_scene(portable_scene(scene)))throw std::runtime_error("Shared scene contains personal paths, media, notes or location data. Export it through NovaTune first.");return scene;}
}
